// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

// new_hire contract (FormContracts.js, verified:true). Unknown keys are rejected by Forms with E_VALIDATION → only pass contract keys.
const REQUIRED = ['firstName','lastName','hireDate','requesterEmail','reportingManagerName','reportingManagerEmail','positionTitle','siteName','jobSiteNumber','employmentType','employeeType','newHireOrRehire','systemAccess'];
const OPTIONAL = ['requesterName','dateRequested','middleName','preferredName','systems','equipment','googleEmail','googleDomain','computerRequestType','computerType','computerPreviousUser','computerPreviousType','computerSerialNumber','office365Required','creditCardUSA','creditCardLimitUSA','creditCardCanada','creditCardLimitCanada','creditCardHomeDepot','creditCardLimitHomeDepot','phoneRequestType','phonePreviousUser','phonePreviousNumber','bossJobSites','bossCostSheet','bossCostSheetJobs','bossTripReports','bossGrievances','jonasJobNumbers','jrRequired','jrAssignment','plan306090','comments','adpSites','department','purchasingSites','adpSalaryAccess','bossTrainingOnly','existingInternalEmployeeId'];
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
if (!empty(inp.systems)) data.systems = asArr(inp.systems);
if (!empty(inp.equipment)) data.equipment = asArr(inp.equipment);
if (empty(data.dateRequested)) data.dateRequested = $now.toFormat('yyyy-MM-dd');
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: new_hire missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k));
if (unknown.length) throw new Error('EFX E_VALIDATION: new_hire unknown field(s) (not in contract): ' + unknown.join(', '));
const include = bool(inp.includeRecord, false) ? ['record'] : [];
return [{ json: Object.assign({ fn: 'n8n_createInitialRequest', args: [data, include] }, passthru) }];
